args.command:
perl -e '
use strict; use warnings;
my $root = "/bench/repo";

my @entities = qw(
  User Memo Attachment MemoRelation MemoShare Reaction Inbox
  IdentityProvider InstanceSetting UserIdentity UserSetting
);

my @files;
for my $dir (qw(cmd internal server)) {
  push @files, glob("$root/$dir/**/*.go");
}

sub pkg_of {
  my ($f) = @_;
  open my $fh, "<", $f or return "";
  my $p = "";
  while (<$fh>) { if (/^package\s+(\w+)/) { $p = $1; last; } }
  close $fh;
  # use directory as package key for uniqueness
  my $d = $f; $d =~ s/^\Q$root\E\///; $d =~ s/\/[^\/]+$//;
  return $d;
}

for my $ent (@entities) {
  my %pkgs;
  for my $f (@files) {
    open my $fh, "<", $f or next;
    my $content = do { local $/; <$fh> };
    close $fh;
    next unless $content =~ /\bstore\.(\Q$ent\E\b|\*$ent\b)/ || $content =~ /\[\]\*store\.\Q$ent\E\b/ || $content =~ /\*store\.\Q$ent\E\b/;
    $pkgs{pkg_of($f)} = 1;
  }
  printf "%2d  %-20s\n", scalar(keys %pkgs), $ent;
}
'

